// Executable Epic: set hierarchy + execution fields in one shot. Used by the
// create path (post-insert extras), MCP create/update, the Epic execution
// engine, and the UI hierarchy endpoint. Empty issue_type/exec_status must be
// normalised to 'task'/'idle' by the caller (the CHECK rejects ”).
func (q *Queries) SetIssueExecFields(ctx context.Context, arg SetIssueExecFieldsParams) (Issue, error) {
	row := q.db.QueryRowContext(ctx, setIssueExecFields,
		arg.ParentIssueID,
		arg.IssueType,
		arg.ExecWave,
		arg.ExecStatus,
		arg.ID,
	)
	var i Issue
	err := row.Scan(
		&i.ID,
		&i.ColumnID,
		&i.Title,
		&i.Description,
		&i.Priority,
		&i.Position,
		&i.LifecycleStatus,
		&i.StartDate,
		&i.DueDate,
		&i.EstimateType,
		&i.Estimate,
		&i.ActualTime,
		&i.ExternalSource,
		&i.ExternalID,
		&i.ExternalUrl,
		&i.ExternalSnapshotAt,
		&i.ExternalCommentsSnapshot,
		&i.ExternalCommentsSnapshotAt,
		&i.GoalCondition,
		&i.ParentIssueID,
		&i.IssueType,
		&i.ExecWave,
		&i.ExecStatus,
		&i.ExecStatusReason,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.CreatedBy,
	)
	return i, err
}

